mapper.select:
SELECT LANG_GB, LANG_KEY, MESSAGE_CNS FROM ( SELECT BASE.LANG_GB, BASE.LANG_KEY, GROUP_CONCAT( CONCAT(B.DETAIL_CODE_VALUE, ':', IFNULL(M.MESSAGE_CN, '')) ORDER BY B.SORTING_SQ SEPARATOR '|' ) AS MESSAGE_CNS FROM ( SELECT DISTINCT CMPNY_CD, LANG_GB, LANG_KEY FROM CM_MESSAGE_LANG WHERE 1=1
AND CMPNY_CD = #{cmpnyCd}
AND LANG_GB = #{category}
) BASE CROSS JOIN ( SELECT DETAIL_CODE_VALUE, SORTING_SQ FROM CM_CODE_DETAIL WHERE CODE_ID = 'CMMNCODE.100'
AND CMPNY_CD = #{cmpnyCd}
AND USE_FL = 'Y' ) B LEFT JOIN CM_MESSAGE_LANG M ON M.LANG_GB = BASE.LANG_GB AND M.LANG_KEY = BASE.LANG_KEY AND M.CMPNY_CD = BASE.CMPNY_CD AND M.LANG_CODE = B.DETAIL_CODE_VALUE GROUP BY BASE.CMPNY_CD, BASE.LANG_GB, BASE.LANG_KEY ) A WHERE 1=1
AND LANG_GB = #{category}
AND ( LANG_KEY LIKE CONCAT('%', #{searchCondition}, '%') OR MESSAGE_CNS LIKE CONCAT('%', #{searchCondition}, '%') )
ORDER BY LANG_GB, LANG_KEY LIMIT #{recordCountPerPage} OFFSET #{offset}

SELECT COUNT(*) FROM ( SELECT BASE.LANG_GB, BASE.LANG_KEY, GROUP_CONCAT( IFNULL(M.MESSAGE_CN, '') ORDER BY B.SORTING_SQ SEPARATOR '|' ) AS MESSAGE_CNS FROM ( SELECT DISTINCT CMPNY_CD, LANG_GB, LANG_KEY FROM CM_MESSAGE_LANG WHERE 1=1
AND CMPNY_CD = #{cmpnyCd}
AND LANG_GB = #{category}
) BASE CROSS JOIN ( SELECT DETAIL_CODE_VALUE, SORTING_SQ FROM CM_CODE_DETAIL WHERE CODE_ID = 'CMMNCODE.100'
AND CMPNY_CD = #{cmpnyCd}
AND USE_FL = 'Y' ) B LEFT JOIN CM_MESSAGE_LANG M ON M.LANG_GB = BASE.LANG_GB AND M.LANG_KEY = BASE.LANG_KEY AND M.CMPNY_CD = BASE.CMPNY_CD AND M.LANG_CODE = B.DETAIL_CODE_VALUE GROUP BY BASE.CMPNY_CD, BASE.LANG_GB, BASE.LANG_KEY ) A WHERE 1=1
AND LANG_GB = #{category}
AND ( LANG_KEY LIKE CONCAT('%', #{searchCondition}, '%') OR MESSAGE_CNS LIKE CONCAT('%', #{searchCondition}, '%') )

SELECT 
    M.LANG_GB AS langGb,
    M.LANG_KEY AS langKey
FROM CM_MESSAGE_LANG M
WHERE 1 = 1

AND M.CMPNY_CD = #{cmpnyCd}

AND M.LANG_GB  = #{langGb}
AND M.LANG_KEY = #{langKey}
LIMIT 1

SELECT CD.DETAIL_CODE_VALUE AS langCode, IFNULL(B.MESSAGE_CN, CD.DETAIL_CODE_VALUE) AS langName, M.MESSAGE_CN AS messageCn FROM CM_CODE_DETAIL CD LEFT JOIN CM_MESSAGE_LANG B ON B.LANG_KEY = CD.CODE_LANG_KEY AND B.CMPNY_CD = CD.CMPNY_CD AND B.LANG_CODE = #{langGb} LEFT JOIN CM_MESSAGE_LANG M ON 1 = 1 AND M.LANG_CODE = CD.DETAIL_CODE_VALUE
AND M.CMPNY_CD = #{cmpnyCd}
AND M.LANG_GB = #{langGb} AND M.LANG_KEY = #{langKey} WHERE CD.CODE_ID = 'CMMNCODE.100'
AND CD.CMPNY_CD = #{cmpnyCd}
AND CD.USE_FL = 'Y' ORDER BY CD.SORTING_SQ ASC

SELECT M.LANG_KEY AS langKey, M.MESSAGE_CN AS messageCn
FROM CM_MESSAGE_LANG M
INNER JOIN (
    SELECT LANG_KEY, MAX(CREATION_DT) AS max_dt
    FROM CM_MESSAGE_LANG
    WHERE LANG_CODE = #{langCode}

      AND CMPNY_CD = #{cmpnyCd}

    AND LANG_KEY IN

      #{k}

    GROUP BY LANG_KEY
) T ON M.LANG_KEY = T.LANG_KEY AND M.CREATION_DT = T.max_dt
WHERE M.LANG_CODE = #{langCode}

  AND M.CMPNY_CD = #{cmpnyCd}

mapper.delete:
DELETE FROM CM_MESSAGE_LANG
WHERE 1 = 1
AND CMPNY_CD = #{cmpnyCd}
AND LANG_GB  = #{langGb}
AND LANG_KEY = #{langKey}
